// Reviewed, algorithm-specific predictions against the fixed reference examples.
// Each row is: revealed trace index, question, answer, distractor~feedback,
// distractor~feedback, gentle hint, concrete hint. The compiler only binds
// assertions/code references; it never invents a question or an answer.
import fs from 'node:fs';
const authored = new Map();
function add(number, intro, commonMistake, rows) { authored.set(number, { intro, commonMistake, rows }); }

add(238, 'Build a new array where each position contains the product of every other number.', 'Writing the prefix after multiplying the current number accidentally includes the number we must exclude.', [
[3,'At the first position, what product belongs to its left?','1, because there are no numbers to the left','0~Zero would make every later multiplication zero.','The first number~The current number must be excluded.','Think of the starting value for multiplication.','Multiplying by 1 leaves a product unchanged.'],
[19,'The left product at index 2 is 2 and the right product is 4. What is written?','8','6~These products are multiplied, not added.','24~That includes the value 3 at the current index.','Combine the two sides without using nums[2].','The calculation is 2 times 4.'],
[27,'Which array excludes each original position from its product?','[24, 12, 8, 6]','[24, 24, 24, 24]~That includes every position each time.','[1, 1, 2, 6]~Those are only the left-side products.','Each output needs a left and a right product.','For index 1, multiply 1, 3, and 4.']]);
add(239,'Move a three-number window across the array and report the largest number in each window.','Keeping a smaller older number behind a larger newer one adds work without helping any future maximum.',[
[5,'When 3 arrives, what happens to the older 1 at the deque back?','Remove 1','Keep 1 in front~The newer 3 is larger and lasts longer.','Remove 3~The incoming larger value can be a future maximum.','Compare both value and how long each stays in the window.','3 dominates 1 until 1 would leave anyway.'],
[10,'The first full window is [1, 3, -1]. Which maximum is appended?','3','1~The maximum is read at the deque front, not the window start.','-1~The newest value need not be largest.','Look at the oldest surviving candidate in the deque.','Its index is 1 and its value is 3.'],
[32,'How many maxima are produced by eight values with a window of three?','6: [3, 3, 5, 5, 6, 7]','8~The first two incomplete windows produce no output.','3~Three is the window width, not the number of windows.','Count starts from index 0 through index 5.','There are n - k + 1 complete windows.']]);
add(242,'Check whether two words use exactly the same letters the same number of times.','Matching the set of letters is insufficient; repeated letters must also have equal counts.',[
[1,'What must be checked before comparing letter counts?','The strings have equal length','The strings have identical order~Anagrams may reorder letters.','Both start with the same letter~First letters may differ in anagrams.','One extra character already prevents a match.','Equal frequencies imply equal total lengths.'],
[6,'After counting s[0] = a, how does t[0] = n affect the frequency table?','Decrease the n slot by 1','Increase the n slot~Letters from t cancel letters from s.','Decrease the a slot~Each letter has its own slot.','The two strings contribute opposite signs.','s adds; t subtracts at its own letter index.'],
[34,'Every final frequency is zero. Are these two words anagrams?','Yes','No, because the order differs~Anagrams specifically allow a different order.','Only if no letter repeats~Repeated letters are allowed when counts match.','A zero slot means the two words used that letter equally.','All 26 differences are zero.']]);
add(252,'Decide whether one person can attend all meetings without overlapping times.','A meeting that begins exactly when another ends does not overlap; the test uses a strict less-than comparison.',[
[1,'Which ordering makes conflicts easy to find next to each other?','Increasing start time','Increasing duration~Duration does not put neighboring meetings in time order.','Decreasing end time~The scan expects starts in ascending order.','Think of arranging appointments on a calendar.','Compare the next start against the previous end.'],
[3,'The next meeting starts at 5 while the previous one ends at 30. Do they overlap?','Yes: 5 is before 30','No: their starts differ~Different starting times can still overlap.','Only if they end together~Equal ends are not required for a conflict.','The first meeting is still in progress at time 5.','The condition is 5 < 30.'],
[4,'After finding this overlap, what can the function return immediately?','false','true~A single conflict prevents attending every meeting.','The number 2~This problem asks feasibility, not room count.','One counterexample settles the question.','A person cannot be in these two meetings at once.']]);
add(253,'Find how many meeting rooms are needed at the busiest moment.','The final number of active rooms is not the answer; retain the largest simultaneous count.',[
[5,'The next start is 0 and the next end is 10. Which event happens first?','A meeting starts','A room becomes free~Time 10 is later than time 0.','Both happen together~The times are different.','Compare the next unused start and end.','0 is less than 10.'],
[16,'An end at 10 comes before the next start at 15. How many active rooms remain?','1','2~An ending meeting frees one of the two active rooms.','0~Only one meeting ends at this event.','One of two overlapping meetings has finished.','Decrease rooms from 2 by 1.'],
[25,'The active count fell and rose again. What is the minimum required room count?','2','1~The earlier overlap still required two rooms.','3~Three meetings do not all overlap.','Use the recorded peak, not the last event alone.','maxRooms remained 2.']]);
add(261,'Check whether the undirected graph connects all nodes without any cycle.','Having n - 1 edges is necessary but still requires a cycle or connectivity check.',[
[1,'The graph has five nodes and four edges. What must we check next?','Whether any edge closes a cycle','Return true immediately~An edge count alone does not rule out a cycle and disconnected node.','Require a fifth edge~A tree with five nodes has four edges.','The edge count has passed only one part of the test.','Union-find detects an edge within an existing component.'],
[4,'The roots for nodes 0 and 1 differ. What does their union do?','Join their components without making a cycle','Reject the edge as a cycle~Different roots mean the nodes were disconnected.','Delete both nodes~Union changes parent links, not graph membership.','A new bridge between separate components is safe.','Attach root 0 under root 1.'],
[14,'Four edges were joined without a cycle. Is this five-node graph a tree?','Yes','No, because some nodes have several neighbors~Branches are allowed in a tree.','No, because every node needs degree 2~That requirement describes a cycle, not a tree.','Use both the edge count and successful unions.','n - 1 acyclic edges connect all n nodes.']]);
add(268,'Find the one missing number from the range 0 through the array length.','The XOR seed includes n because the array indices stop at n - 1; the missing value is not always n.',[
[1,'Starting from res = 3, what does XOR with index 0 and value 3 produce?','0','3~The two copies of 3 cancel.','6~XOR is not addition.','Equal numbers XOR to zero.','3 XOR 0 XOR 3 equals 0.'],
[2,'Now res is 0, index is 1, and value is 0. What remains after XOR?','1','0~The unmatched index 1 must still be included.','2~No value 2 has entered this operation.','Zero does not change an XOR result.','0 XOR 1 XOR 0 equals 1.'],
[4,'After all index/value pairs cancel, which number remains missing?','2','3~3 appeared in the input and canceled its seed.','0~0 is already in the input.','Only an unmatched range value survives.','The final accumulator is 2.']]);
add(269,'Infer a valid alphabet order from a dictionary whose words are already sorted.','Only the first differing character of adjacent words establishes their ordering constraint.',[
[3,'Comparing wrt and wrf, which ordering edge is justified?','t before f','w before r~Shared prefixes do not reveal their internal alphabet order.','f before t~The earlier word supplies the earlier differing character.','Skip the shared prefix wr.','The first difference is t versus f.'],
[13,'After taking w from the queue, which character becomes available?','e','f~f still depends on t.','t~t still depends on r.','Follow the outgoing edge from w.','Removing w satisfies the only prerequisite of e.'],
[22,'Which complete alphabet order follows all discovered edges?','wertf','wrtfe~e must occur before r.','ftrew~This reverses the dependency direction.','Read the characters in the order removed from the queue.','The chain is w, then e, r, t, f.']]);
add(271,'Pack a list of strings into one string while preserving exact boundaries.','Splitting only on # fails when a string itself contains #; the length tells the decoder how much to read.',[
[3,'How is the first string neet represented?','4#neet','neet#~The decoder needs a length before the content.','3#neet~neet has four characters.','Write its character count, then a delimiter, then its text.','The length of neet is 4.'],
[7,'What is appended for the second string code?','4#code','code4~The length prefix must come before the content.','8#code~Each prefix describes only its own string.','Use the same independent length prefix for every item.','code also has length 4.'],
[18,'What complete encoded stream is returned?','4#neet4#code4#love3#you','neet#code#love#you~Delimiters alone do not preserve arbitrary string contents.','4#neet4#code4#love4#you~you has length 3, not 4.','Concatenate all four length-prefixed pieces.','The final piece is 3#you.']]);
add(279,'Make the target number using the fewest perfect square numbers.','Choosing the largest square greedily can miss a solution with fewer squares.',[
[3,'To make 1 using square 1, which earlier answer supplies the remainder?','dp[0], giving one square','dp[1]~That is the value currently being solved.','dp[2]~Subtracting a positive square cannot increase the remainder.','Remove the chosen square from the target.','1 - 1 leaves zero, whose cost is zero.'],
[29,'For total 8, using square 4 leaves another 4. What count replaces 5?','2','4~Count squares rather than their numerical sum.','1~A single perfect square cannot equal 8.','dp[4] is 1.','Add one new square to that one-square solution.'],
[51,'What is the fewest number of squares that sum to 12?','3','2~No two perfect squares sum to 12.','4~4 + 4 + 4 uses only three.','The repeated square 4 is allowed.','Three copies of 4 total 12.']]);
add(286,'Fill each empty room with its shortest walking distance to any gate.','Starting a separate search from each room repeats work; all gates should start the same breadth-first wave.',[
[1,'Both gates begin in the frontier. What distance will their empty neighbors receive?','1','0~Only the gates themselves have distance zero.','2~An adjacent room is only one move away.','One breadth-first layer is one walking step.','The current gate distance is zero, so add one.'],
[7,'Room (1,2) has distance 1. What is written into its empty neighbor (2,2)?','2','1~Moving to a neighboring room costs another step.','Infinity~The neighbor is reachable from this frontier.','Extend an already shortest route by one edge.','1 + 1 equals 2.'],
[20,'After the queue drains, what does any remaining Infinity mean?','No gate can reach that room','It is a gate~Gates are represented by 0.','It needs one more BFS layer~An empty queue means there are no reachable frontier cells left.','The waves have explored every reachable room.','Walls can isolate rooms from every gate.']]);
add(287,'Find the repeated array value by following values as links between indices.','The first meeting is inside the cycle; reset one pointer before identifying the cycle entrance.',[
[2,'The fast and slow runners meet at 2 during phase 1. What has this proved?','They are inside a cycle','The whole search is finished in every case~The first meeting need not be the entrance.','The array is sorted~Pointer convergence says nothing about sorted order.','A faster runner catches a slower one only after entering the loop.','Phase 2 still identifies the entrance.'],
[3,'How does phase 2 start after the first meeting?','Reset slow to nums[0] and keep fast at 2','Reset both to nums[0]~Both would meet immediately without locating the entrance.','Keep fast moving twice as quickly~Phase 2 uses equal speeds.','Keep one anchor inside the cycle.','Only slow returns to the starting link.'],
[6,'The equal-speed runners meet at the entrance 2. Which value is duplicated?','2','1~That is the starting link, not the cycle entrance.','4~4 lies on the cycle but is not its entry.','Multiple links point into the entrance.','Return the entrance value.']]);
add(295,'Maintain the middle value of a stream without sorting the entire stream after every insertion.','The heaps must satisfy both ordering and size balance; checking only their sizes is not enough.',[
[10,'After inserting 1 and 2 into the lower heap, is its size balanced?','No; move its maximum to the upper heap','Yes; any size difference is allowed~The halves must differ by at most one.','No; move its minimum~The largest lower-half value belongs at the boundary.','The lower heap has two values and the upper has none.','A size difference of two requires one transfer.'],
[11,'Which number moves from the lower max-heap to the upper min-heap?','2','1~The transfer removes the max-heap root.','Both~Moving one value restores balance.','Move the boundary value between the two halves.','The largest of 1 and 2 is 2.'],
[24,'With the stream [1,2,3], the upper heap has one extra value. What is the median?','2','1.5~An odd count does not average two roots.','3~The upper heap root is its minimum, not maximum.','Use the root of the larger heap.','The sorted middle of 1,2,3 is 2.']]);
add(297,'Turn a binary tree into a string and rebuild the same values and child positions.','Omitting null children loses the shape even when every real node value is recorded.',[
[2,'After recording node 1 in preorder, which child is visited next?','Its left child','Its right child~This traversal records left before right.','The root again~The root value has already been recorded.','Preorder means node, left subtree, right subtree.','Follow the left link from 1.'],
[5,'The left child of node 2 is missing. What must be added to the serialized sequence?','A null marker','Nothing~An explicit gap is needed to reconstruct child positions.','The number 0~Zero could be a real node value.','The encoding records shape as well as values.','Missing children are represented by the text null.'],
[61,'What should match after deserialize finishes?','Both the original node values and tree shape','Only the sorted values~Sorting loses which node is a child of which.','Only the number of nodes~Different trees can have the same node count.','A round trip restores the original structure.','The rebuilt level-order representation matches the input.']]);
add(300,'Find the longest sequence of increasing numbers while keeping their original order.','A subsequence may skip positions, but equal values cannot extend a strictly increasing chain.',[
[2,'Can the earlier 10 precede 9 in an increasing subsequence?','No','Yes, because it appeared first~Both index order and increasing value are required.','Only if they are adjacent~Adjacency is not the requirement.','Check the values as well as their positions.','10 is not less than 9.'],
[27,'A chain of length 2 ends at 5. Appending 7 makes what length?','3','2~Appending a new element adds one to the chain length.','7~The DP stores length, not the ending value.','The earlier smaller value supplies its best chain.','dp[3] + 1 is 2 + 1.'],
[60,'What is the longest increasing subsequence length in this example?','4','8~Not every input value can be included in increasing order.','3~A chain such as 2,3,7,18 has four values.','Keep the largest endpoint-specific DP result.','A four-element chain exists even though positions are skipped.']]);
add(304,'Precompute rectangle sums so later queries can be answered with four table reads.','Adding above and left counts their overlap twice; subtract it once during construction.',[
[3,'When adding the rectangles above and left, what must happen to their shared area?','Subtract it once','Add it again~It has already been counted twice.','Ignore it~The two rectangle sums both contain it.','Sketch the overlap between the two rectangles.','Inclusion-exclusion removes the duplicate copy.'],
[40,'For prefix[3][3], compute 18 + 17 - 14 + 0. What is stored?','21','35~The overlap 14 must be removed.','49~Adding the overlap increases the double counting.','Use above plus left minus overlap plus the source cell.','35 - 14 equals 21.'],
[83,'The query uses 38 - 24 - 14 + 8. What rectangle sum is returned?','8','0~The corner overlap must be added back.','38~That includes cells above and left of the requested rectangle.','The two subtracted strips overlap.','14 - 14 + 8 equals 8.']]);
add(309,'Maximize stock profit while taking a full cooldown day after every sale.','Buying from yesterday\'s sold state would violate the cooldown; buy only from yesterday\'s rest state.',[
[2,'On day 1, keeping the share gives -1 while buying today gives -2. Which holding profit wins?','-1','-2~We maximize profit even when both candidates are negative.','1~Selling is a different state from holding.','Compare the two ways to end today with a share.','The larger of -1 and -2 is -1.'],
[15,'On day 3, buying at price 0 from a rested profit of 1 gives what holding profit?','1','0~The earlier earned profit is not discarded.','2~The sold state from yesterday is still cooling down.','A purchase subtracts its price from the rested profit.','1 - 0 equals 1.'],
[26,'At the end, sold = 3 and rest = 2. What realized profit is returned?','3','2~Ending with a sale is allowed.','The holding state~Unsold shares are not realized final profit.','Choose the best state that owns no share.','max(3,2) is 3.']]);
add(310,'Find the tree root or roots that make the tree as short as possible.','Remove all leaves in a round together; peeling one at a time can bias the center.',[
[4,'Which nodes form the initial outer leaf layer?','[0, 2, 3]','[1]~Node 1 has three neighbors, so it is not initially a leaf.','[0, 1, 2, 3]~Only degree-one nodes are leaves.','Count each node\'s neighbors.','The three endpoints each connect only to node 1.'],
[6,'Removing the three current leaves from four nodes leaves how many centers to consider?','1','3~Three is the number being removed.','0~The center node is not in this leaf layer.','Subtract the entire layer from remaining.','4 - 3 equals 1.'],
[11,'Which node survives as the minimum-height root?','1','0~0 was peeled as an outer leaf.','All four~Only the central survivor minimizes maximum depth.','Stop when at most two nodes remain.','The next leaf frontier contains only node 1.']]);
add(312,'Choose the balloon bursting order that earns the most coins.','Choose the last balloon in a subinterval; choosing the first changes its remaining neighbors unpredictably.',[
[2,'For the interval bounded by 1 and 1 with balloon 3 inside, how many coins are earned?','3','5~The neighboring values are multiplied, not added.','1~The balloon value also participates in the product.','This interval has just one possible last balloon.','1 times 3 times 1 equals 3.'],
[19,'Bursting 5 last between boundaries 3 and 8 gives 120 plus the solved left interval 15. What total wins?','135','120~The already burst subinterval contributes its coins too.','64~That was the previous candidate, now improved.','Combine the boundary product and both subproblem totals.','120 + 15 + 0 equals 135.'],
[41,'What maximum is returned for all four original balloons?','167','162~A later last-balloon choice improves this candidate.','24~The answer is not simply the product of the input.','Read the DP interval between the outer sentinels.','Its best last balloon is 8 and its total is 167.']]);
add(322,'Make the requested amount using as few coins as possible; each denomination can be reused.','The DP stores coin counts, not sums, and unreachable amounts begin at Infinity rather than zero.',[
[4,'While solving amount 1, can coin 2 be used?','No; skip it','Yes, once~That overshoots the amount.','Yes, with a negative remainder~Negative amounts are outside this DP.','A chosen coin must fit in the current amount.','2 is greater than 1.'],
[28,'For amount 6, using coin 1 leaves amount 5 with cost 1. What count is proposed?','2','6~The stored answer counts coins rather than their value.','1~The additional coin 1 must be counted.','Add one chosen coin to the best remainder solution.','dp[5] + 1 equals 2.'],
[57,'What is the minimum coin count for amount 11 with coins 1,2,5?','3','2~Two coins can total at most 10.','11~Using only ones is valid but not minimal.','Try two fives and one one.','5 + 5 + 1 uses three coins.']]);
add(323,'Count the separate groups of nodes connected by undirected edges.','An edge decreases the component count only when its endpoints previously belonged to different groups.',[
[2,'For the first edge [0,1], do its endpoints currently share a root?','No; roots are 0 and 1','Yes, because an edge is listed~The edge has not been unioned yet.','Every node starts with root 0~Initially each node is its own component.','Union-find begins with five separate groups.','Compare the roots 0 and 1.'],
[3,'Joining those two components changes the count from 5 to what?','4','3~One merge reduces the count by one, not two.','5~The two separate groups have become one.','Two old components are replaced by one combined component.','5 - 1 equals 4.'],
[10,'After all three successful joins, how many connected groups remain?','2','1~No edge joins the group {0,1,2} to {3,4}.','3~Three is the number of edges, not components.','Identify the two disjoint sets in the diagram.','Five starting components minus three merges leaves two.']]);
add(329,'Find the longest strictly uphill path through neighboring matrix cells.','An equal-valued neighbor cannot extend a strictly increasing path; this also prevents cycles.',[
[5,'From value 9, may the search move down to value 6?','No','Yes, because they are neighbors~The value must also be strictly greater.','Yes, if 6 was not visited~Visited status cannot make a downhill move valid.','This path must increase at every move.','6 is less than 9.'],
[57,'The neighbor path has length 1. Including the current 6 makes what candidate length?','2','1~The current cell adds one to the neighbor path.','6~The DP stores path lengths, not heights.','Attach the current cell before the known neighbor path.','1 + 1 equals 2.'],
[109,'After checking every starting cell, what longest path length is returned?','4','9~There are nine cells but they cannot all form one increasing path.','1~Several lower cells can climb through multiple larger neighbors.','Use the maximum memoized starting-path length.','A path 1,2,6,9 contains four cells.']]);
add(332,'Use every flight ticket once to construct the lexicographically smallest itinerary from JFK.','Appending airports before consuming their outgoing tickets can get stuck; record them on return and reverse at the end.',[
[5,'From JFK, which ticket is selected next?','JFK to MUC','JFK to SJC~There is no such outgoing ticket here.','MUC to LHR~The current airport is JFK.','Choose an unused destination from the current airport.','JFK has MUC as its only destination.'],
[17,'SJC has no unused outgoing tickets. What is appended to the reverse result?','SJC','JFK~The function records the airport whose visit is finishing.','Nothing~Dead ends are recorded as the recursion unwinds.','Postorder records an airport after its outgoing edges.','The current completed airport is SJC.'],
[26,'How is the postorder airport list turned into the final itinerary?','Reverse it','Sort it alphabetically~Sorting would break ticket connections.','Remove the first airport~Every endpoint is needed in the route.','The final destination was recorded first.','Reversal puts JFK first and SJC last.']]);
add(337,'Choose houses in a tree for maximum money without robbing both a parent and its child.','A parent needs both child answers, rob and skip; returning only one best total loses the adjacency constraint.',[
[5,'What pair does an absent child contribute?','[0, 0]','[1, 0]~A missing house cannot contribute money.','[0, 1]~Skipping a missing house also contributes zero.','Neither robbing nor skipping an empty subtree earns anything.','Both alternatives have value zero.'],
[34,'If the root worth 3 is robbed, its children must be skipped for 3 and 1. What is earned?','7','8~That would combine an incompatible child choice.','3~Skipping a child still permits robbing its descendants.','Add the root to each child\'s skip result.','3 + 3 + 1 equals 7.'],
[37,'The root pair is [7,6]. What maximum money is returned?','7','6~Skipping the root is optional, not mandatory.','13~The two alternatives cannot both be taken.','Choose the better of rob-root and skip-root.','max(7,6) is 7.']]);
add(338,'Count the number of 1 bits in every integer from zero through the target.','The low bit contributes only 0 or 1; shifting reuses an already solved smaller integer.',[
[1,'For i = 1, the shifted value is 0 and the low bit is 1. What count is stored?','1','0~The low bit still needs to be added.','2~There is only one bit set in binary 1.','Reuse dp[0] and add the removed low bit.','0 + 1 equals 1.'],
[2,'For binary 10 (decimal 2), how many set bits are stored?','1','2~The number of bit positions is not the number of ones.','0~The high bit is still set after shifting.','Shift to binary 1; the removed low bit is zero.','dp[1] + 0 equals 1.'],
[3,'Which array counts the 1 bits in 0, 1, and 2?','[0, 1, 1]','[0, 1, 2]~Decimal 2 is binary 10 and has one set bit.','[1, 1, 1]~Zero has no set bits.','Read the counts in numeric order.','The counts for 0,1,10 in binary are 0,1,1.']]);

add(343,'Split a positive integer into at least two positive parts and maximize their product.','The original integer cannot be returned whole; the final answer must use at least one split.',[
[2,'Before solving target 2, which choice is a legal integer break?','Split it into 1 + 1','Keep 2 whole~At least two positive parts are required.','Split it into 0 + 2~Every part must be positive.','The chosen parts must be positive and there must be at least two of them.','The only legal positive split of 2 is 1 + 1.'],
[3,'The only split of 2 is 1 + 1. What product is stored?','1','2~The objective multiplies the parts, rather than adding them.','0~Both parts are positive ones.','Multiply the two parts of the split.','1 times 1 is 1.'],
[4,'What does integerBreak(2) return after the table is filled?','1','2~Keeping 2 whole violates the required split.','3~The parts sum to 2 and cannot produce 3.','Read the best product for the target, not the target itself.','dp[2] was set to 1.']]);
add(344,'Reverse the characters by swapping matching positions from the two ends inward.','The pointers must move together; a middle character in an odd-length array needs no swap.',[
[1,'With left = 0 and right = 4, should another pair be swapped?','Yes','No, because the indices differ~Different ordered endpoints are exactly when swapping is needed.','Only if the characters are equal~Reversal does not require equal characters.','Continue while the left pointer is before the right pointer.','0 < 4 is true.'],
[2,'Which positions are exchanged in the first swap of hello?','0 and 4','0 and 1~Adjacent swaps are not this two-pointer reversal.','1 and 3~Those are the next inner pair.','The pointers begin at opposite ends.','Exchange the h and the o.'],
[9,'After both outer pairs are swapped, what string remains?','olleh','hello~Both swaps change the order.','olelh~The second swap must also reverse e and l.','Read the original characters from right to left.','o, l, l, e, h is the reversed order.']]);
add(347,'Find the two values that occur most often in the input.','A bucket index is a frequency; the values inside that bucket are the original numbers.',[
[4,'The second occurrence of value 1 has arrived. What frequency is recorded?','2','1~Both appearances of 1 must be counted.','3~Only two copies have been processed so far.','Increase the existing count by one.','1 previous occurrence plus this occurrence makes 2.'],
[15,'Value 1 appeared three times. Which frequency bucket receives it?','bucket[3]','bucket[1]~The bucket is selected by frequency, not by the value itself.','bucket[0]~An observed value has positive frequency.','The bucket number answers how often, not which number.','freq.get(1) is 3.'],
[32,'Which two values are returned after scanning buckets from high frequency to low?','[1, 2]','[2, 3]~Value 1 is the most frequent and cannot be omitted.','[3, 2, 1]~Only k = 2 values are requested.','The frequencies are 3 for value 1 and 2 for value 2.','Stop as soon as two values have been collected.']]);
add(355,'Build a feed containing the newest tweets from a user and the accounts they follow.','Tweet IDs are identifiers, not timestamps; feed order follows posting time.',[
[5,'Whose tweets belong in user 1\'s feed before following anyone?','User 1\'s own tweets','Nobody\'s tweets~A user sees their own posts even without followees.','Every user\'s tweets~The feed includes only self and followed accounts.','The feed explicitly adds the requesting user to the source set.','The source set currently contains only 1.'],
[20,'When user 2\'s tweet 6 is added to the feed heap, what orders it against other tweets?','Its timestamp 1','Its tweet ID 6~An ID need not increase with time.','The user number 2~User identity does not determine recency.','The heap compares the first item of each [time, tweetId] pair.','The later time is the newer tweet.'],
[38,'After user 1 unfollows user 2, which feed is returned?','[5]','[6, 5]~Tweet 6 belongs to an account no longer followed.','[]~User 1\'s own tweet remains visible.','Rebuild the feed from the current following set.','Only user 1 contributes a timeline now.']]);
add(371,'Add two integers by combining their bits and carrying overlaps to the next column.','Compute the carry before replacing a; otherwise the shared original bits are lost.',[
[2,'Binary 01 and 10 have no shared 1 column. What is their carry?','0','1~No column contains two ones.','3~3 is the sum without carry, not the carry.','AND keeps only columns set in both operands.','01 AND 10 is 00, and shifting zero remains zero.'],
[3,'What does 1 XOR 2 produce before adding any carry?','3','0~XOR keeps columns that differ.','2~Both differing bit positions remain set.','The bit patterns are 01 and 10.','Their XOR is binary 11.'],
[6,'The carry is now zero. Which final value is returned?','3','0~Zero is the remaining carry, not the accumulated sum.','2~That was the second input, before addition.','No carry means the partial sum is complete.','a now holds 3.']]);
add(374,'Find a hidden number by using higher-or-lower feedback to halve its possible range.','A failed midpoint must be excluded with mid + 1 or mid - 1, or the search may stop shrinking.',[
[4,'The guess service says the midpoint is too low. Where is the hidden number?','Above the midpoint','Below the midpoint~The feedback says the guess needs to increase.','At the midpoint~A correct guess would return zero.','Too low means the current guess is smaller than the answer.','Search the higher half.'],
[10,'A later midpoint is too high. How does the upper boundary change?','right = mid - 1','left = mid + 1~That would move toward even larger guesses.','right = mid + 1~That retains the rejected midpoint and a larger value.','Exclude the midpoint and everything larger.','The final allowed value below mid is mid - 1.'],
[16,'Which hidden number does the final matching guess identify?','6','5~The first midpoint was too low.','8~The later midpoint was too high.','The final service response was zero.','The matching midpoint is 6.']]);
add(377,'Count ordered sequences of reusable numbers that add to the target.','Order matters here: 1 then 2 is a different sequence from 2 then 1.',[
[1,'How many sequences make total zero before any number is chosen?','1: the empty sequence','0~The empty sequence is needed to seed one-number sequences.','One for every input number~No number has been chosen at total zero.','A valid way to make nothing is to select nothing.','dp[0] must be 1 so appending one fitting number contributes one way.'],
[19,'For total 4, appending 2 adds the two sequences for total 2 to the current 4 ways. What is stored?','6','4~The two additional endings have not yet been counted.','2~Existing sequences must be retained too.','Different choices of the last number form distinct groups.','4 + dp[2] is 4 + 2.'],
[22,'With numbers 1,2,3, how many ordered sequences total 4?','7','4~Four counts combinations without all their distinct orders.','3~There are more sequences than available denominations.','Add the counts for sequences ending in 1, 2, or 3.','Those contributions are 4, 2, and 1.']]);
add(394,'Expand repeated bracketed groups while preserving text outside each group.','Opening a bracket saves both the existing prefix and repeat count, then resets the inner group state.',[
[2,'On the opening bracket in 3[a], what is saved on the stack?','The empty prefix and repeat count 3','Only the letter a~The letter has not been read yet and does not preserve the repetition context.','The finished text aaa~The group is not decoded until its closing bracket.','A nested group needs a place to return to.','Save [current string, current number].'],
[4,'The first closing bracket ends inner text a with repeat count 3. What becomes current text?','aaa','a3~The count controls repetition rather than becoming literal output.','aa~The repeat count is 3, not 2.','Repeat the complete inner text.','a repeated three times is aaa.'],
[10,'After also expanding 2[bc], what final string is returned?','aaabcbc','aaabbcc~Repeat the group bc, not each character independently.','bcbc~The earlier prefix aaa must be preserved.','Concatenate the saved prefix with the repeated second group.','aaa + bc + bc gives the answer.']]);
add(399,'Use known division ratios to answer new ratios by following weighted graph paths.','Multiply edge ratios along a path; reverse edges use reciprocals rather than negation.',[
[3,'If a / b = 2, what weight belongs on the reverse edge b to a?','0.5','-2~Reversing division takes a reciprocal, not a negative.','2~The direction of the ratio matters.','b / a is one divided by a / b.','1 divided by 2 is 0.5.'],
[16,'Along a to b to c, the ratios are 2 and 3. What ratio returns for a / c?','6','5~Path ratios multiply rather than add.','1.5~The two forward edges are not divided.','The intermediate b cancels in (a/b) times (b/c).','2 times 3 equals 6.'],
[32,'The variable x never appeared in any equation. What is returned for x / x?','-1','1~The problem treats unknown variables as undefined even when their names match.','0~Undefined ratios are represented by -1.','Check that the variable exists before applying the identity rule.','x is absent from the graph.']]);
add(410,'Split an array into the requested number of consecutive pieces while minimizing the largest piece sum.','Search for the smallest feasible sum limit; the pieces remain contiguous and cannot reorder values.',[
[7,'At candidate limit 21, adding 10 to the current piece would exceed the limit. What happens?','Start another piece with 10','Skip 10~Every input number must belong to a piece.','Raise this piece above 21~That violates the candidate limit being tested.','A piece ends before the first value that would overflow.','Increment pieces and reset its sum to 10.'],
[29,'A limit of 18 needs only two pieces, matching k. Which direction should the search try next?','Smaller limits','Larger limits only~18 already works; we are minimizing it.','Stop immediately~A smaller feasible limit still must be ruled out.','Remember 18 as an answer while tightening the limit.','Feasibility lets the upper bound move below 18.'],
[53,'What is the smallest possible largest-piece sum for this example?','18','21~21 works but is not minimal.','10~No piece could then accommodate the required two-piece partition.','The best split is [7,2,5] and [10,8].','Their sums are 14 and 18.']]);
add(416,'Decide whether the numbers can be divided into two groups with equal sums.','Sweep capacities downward so one input occurrence cannot be reused repeatedly in the same pass.',[
[2,'The total is 22. What subset target represents an equal partition?','11','22~That would put every value on one side.','2~Two is the number of groups, not the target sum.','Equal groups must each contain half the total.','22 divided by 2 is 11.'],
[15,'The empty subset reaches zero. After processing number 1, which new sum becomes reachable?','1','2~There is only one occurrence of 1 in this pass.','11~One alone cannot reach the full target.','Add this number once to the empty subset.','0 + 1 equals 1.'],
[34,'dp[11] is true. Can the array be split evenly?','Yes','No, because group sizes differ~Equal sums do not require equal numbers of elements.','Only if both groups are adjacent~Subsets need not be contiguous.','The unused numbers total the other half automatically.','A subset of 11 leaves 22 - 11 = 11.']]);
add(417,'Find cells from which water can reach both oceans at the edges of the height map.','The search runs backward from each ocean, so it follows equal or higher terrain rather than downhill.',[
[3,'Starting from ocean-reachable height 1, may the reverse search enter neighboring height 3?','Yes','No, because water cannot flow uphill~This traversal follows the reverse of real water flow.','Only if the height difference is 1~There is no such difference limit.','Ask whether water could flow from 3 back down to 1.','3 is at least the previous height 1.'],
[40,'Atlantic search reaches height 7 from height 6. Which reachability set is marked?','Atlantic','Pacific only~This particular traversal started at the Atlantic border.','Neither~7 can drain downhill to the already Atlantic-reachable 6.','Keep the two ocean searches separate.','Set the Atlantic visited flag for this cell.'],
[79,'Which cells belong in the answer after both searches?','The seven cells reached by both oceans','All cells reached by either ocean~The requirement is both, not either.','Only the border cells~Interior cells may drain to both oceans too.','Intersect the two boolean reachability maps.','Keep a cell only when both flags are true.']]);
add(424,'Find the longest substring that can become one repeated character using at most two replacements.','Required replacements equal window length minus the most common character count, not the number of different letters.',[
[4,'A one-character window has one copy of its most common letter. How many replacements does it need?','0','1~It is already a repeated-character string of length one.','2~The budget is a maximum, not a required number of edits.','Subtract the largest letter count from the window length.','1 - 1 equals 0.'],
[19,'Window ABAB has four characters and two copies of each letter. Is it valid with k = 2?','Yes, it needs two replacements','No, it needs four replacements~Keep either pair of matching letters and replace the other pair.','Yes, it needs zero replacements~A and B are different letters.','Choose either A or B as the final repeated letter.','4 - 2 equals the allowed budget 2.'],
[22,'What longest valid length is returned for ABAB with two replacements?','4','2~The budget is two edits, not a maximum window length of two.','3~All four characters can be made equal.','Both B characters can change to A.','The entire string becomes AAAA.']]);
add(427,'Compress a binary grid into uniform square regions using a quad tree.','Only a completely uniform block may become a leaf; one differing cell forces four smaller quadrants.',[
[4,'The block starts with 0 but its next cell is 1. Can the whole block remain uniform?','No','Yes, if most cells match~Every cell must match for a uniform leaf.','Only the diagonal matters~All cells in the square are checked.','Compare the next cell to the top-left representative.','1 differs from 0, so same becomes false.'],
[7,'The 2 by 2 block is mixed. What subdivision happens next?','Four 1 by 1 quadrants','Two horizontal rows only~A quad tree splits into four squares.','One leaf with average value~The binary grid must be represented exactly.','Halve both the row and column span.','half = 1 creates top-left, top-right, bottom-left, bottom-right.'],
[29,'Once all four quadrants are built, what represents the original mixed block?','An internal node with four children','A leaf with value 0~A mixed block cannot be compressed into one leaf.','Only its top-left child~That would discard three quarters of the grid.','Each child stores one of the four regions.','The parent combines them without claiming uniformity.']]);
add(435,'Remove as few intervals as possible so the remaining intervals do not overlap.','On an overlap, keep the earlier-ending interval because it leaves more space for later choices.',[
[5,'The next interval starts at 2 and the kept interval ends at 2. Does this count as overlap?','No','Yes, because the endpoints touch~Touching endpoints are allowed here.','Only if their lengths match~Duration does not affect this boundary comparison.','The condition uses start < prevEnd.','2 < 2 is false.'],
[9,'Interval [1,3] overlaps the kept interval ending at 3. What changes?','Removal count becomes 1; prevEnd stays 3','prevEnd moves back to 1~prevEnd tracks the end of a kept interval.','Both intervals are removed~Only one needs to be discarded.','Discard the current conflicting interval.','Increment count without changing the kept boundary.'],
[14,'How many intervals must be removed in this example?','1','0~[1,3] conflicts with the earlier kept schedule.','2~Removing [1,3] alone leaves three compatible intervals.','The kept sequence is [1,2], [2,3], [3,4].','Only the extra [1,3] interval is discarded.']]);
add(450,'Delete a value from a binary search tree while preserving its search ordering.','With two children, copy the successor and then remove its original node to avoid leaving a duplicate.',[
[1,'Searching for 3 at root 5, which subtree is searched next?','Left','Right~Larger keys are on the right; 3 is smaller than 5.','Both simultaneously~The BST ordering identifies the only possible side.','Compare the requested key to the current node value.','3 < 5 selects the left link.'],
[6,'The target has two children and successor 4. What value replaces the target value 3?','4','5~The root 5 is not the smallest value in the target\'s right subtree.','2~This implementation uses the successor, not the predecessor.','Use the smallest value larger than the deleted key.','The leftmost node in its right subtree is 4.'],
[7,'After copying 4, what final cleanup preserves the BST?','Delete the original successor node from the right subtree','Leave both copies of 4~The replacement would otherwise duplicate the node value.','Delete the entire right subtree~Its other nodes must be retained.','Copying a value did not remove the old successor node.','Recursively delete key 4 from the target\'s right child.']]);
add(460,'Keep a limited cache that evicts the least frequently used key, breaking ties by age within a frequency group.','A successful get changes frequency and recency; it is not a read-only operation in an LFU cache.',[
[3,'The first insertion sees zero keys in a capacity-two cache. Must anything be evicted?','No','Yes, key 1~The new key has not been inserted and there is free space.','Yes, the oldest key~The cache is empty.','Compare the current size with capacity.','0 is less than 2.'],
[28,'A successful get of key 3 finds frequency 1. What frequency is assigned?','2','1~Accessing an existing key increases its usage count.','0~Frequency never decreases on a successful get.','The touch operation records this new use.','Increment the prior frequency by one.'],
[54,'Key 4 is still in the cache. What does its final get return?','4','2~2 is its updated frequency, not its stored value.','-1~The missing-key result does not apply to an existing key.','Frequency bookkeeping and stored value are separate maps.','keyToVal.get(4) is 4.']]);
add(463,'Measure the exposed boundary around all land cells in the grid.','A shared edge was counted by both land cells, so it removes two from the perimeter total.',[
[2,'The scan reaches grid[0][1] = 1. Does this cell contribute land edges?','Yes','No, because it is on the boundary~Boundary land has exposed edges too.','Only if all neighbors are water~Connected land still contributes some edges.','The value 1 represents land.','Each land cell starts by adding four sides.'],
[22,'The current perimeter is 12 before removing a shared left edge. What remains?','10','11~The shared edge was counted once from each of two cells.','14~A shared edge removes exposed boundary, not adds it.','Cancel both copies of the internal edge.','12 - 2 equals 10.'],
[44,'After all land and shared edges are counted, what perimeter is returned?','16','7~That counts land cells rather than boundary edges.','28~That ignores the internal shared edges.','The answer measures exposed sides.','The final accumulator after shared-edge corrections is 16.']]);
add(473,'Use every matchstick exactly once to build four sides of equal length.','A total divisible by four is only a necessary check; actual sticks must still fit into four sides.',[
[2,'The sticks total 8. How long must each of the four sides be?','2','4~Four is the number of sides, not their length.','8~That is the total perimeter.','Divide the total length equally among four sides.','8 divided by 4 equals 2.'],
[6,'A stick of length 2 fits the empty side 0. What length does that side become?','2','4~Only one stick is added in this step.','0~The successful placement updates the side before recursion.','Add this stick to the side\'s current length.','0 + 2 equals the target 2.'],
[58,'All sticks have been placed into sides of length 2. Can they form a square?','Yes','No, because there are five sticks~A side may contain more than one stick.','Only if every stick has length 2~The two length-one sticks may share one side.','The four side lengths are equal and every stick is used.','Three sides use a 2; the last uses 1 + 1.']]);
add(494,'Assign a plus or minus sign to each number and count assignments that reach the target.','Equal values at different positions are distinct sign choices, and each position may be selected only once.',[
[2,'Total is 5 and target is 3. What sum must the positive subset have?','4','3~The positive sum must also offset the negative subset.','2~That is half the total-target difference, which corresponds to the negative side here.','Use P + N = 5 and P - N = 3.','Adding the equations gives 2P = 8.'],
[14,'After the second 1, how many subsets can make sum 1?','2','1~Choosing the first 1 differs from choosing the second position.','3~The empty subset does not sum to 1.','Each of the two positions can be chosen by itself.','The prior one way gains one more from dp[0].'],
[30,'How many sign assignments make target 3 from five ones?','5','1~The minus sign may be placed on any of five positions.','10~That would count a different subset size.','Exactly one of the five ones must be negative.','There are five choices for its position.']]);
add(502,'Choose at most two affordable projects to maximize final capital.','Among currently affordable projects, choose highest profit; required capital is a threshold, not a cost to subtract.',[
[4,'With capital 0, may a project requiring capital 0 enter the profit heap?','Yes','No, because capital must be strictly greater~The requirement allows equality.','Only after completing another project~It is affordable immediately.','Compare requirement <= available capital.','0 <= 0 is true.'],
[21,'After earning the first profit, capital is 1. Choosing profit 3 changes capital to what?','4','3~Existing capital remains and the profit is added.','0~Required capital is not spent as a project price.','Add the selected profit to the current capital.','1 + 3 equals 4.'],
[22,'After two projects, what maximum capital is returned?','4','3~Choosing profit 2 second would miss the better available profit 3.','6~Only two projects may be selected.','The chosen profits were 1 and 3.','Starting at zero, their sum is 4.']]);
add(518,'Count distinct coin combinations that make an amount, allowing each denomination to be reused.','Coin order does not create a new combination; organize choices by denomination to avoid permutation duplicates.',[
[1,'How many combinations make amount zero with any prefix of the coin list?','1: choose no coins','0~That would prevent exact one-coin solutions from being counted.','One per denomination~The empty selection is a single combination.','The no-coins choice works regardless of available denominations.','Every row starts with dp[i][0] = 1.'],
[31,'For amount 5, three ways already avoid coin 5. Adding the single-5 combination gives how many?','4','3~The new denomination adds another valid combination.','5~The coin\'s value is not the number of new ways.','Use dp[3][0] = 1 for the remainder after taking coin 5.','3 + 1 equals 4.'],
[32,'Which count is returned for amount 5 using denominations 1,2,5?','4','9~Reordering the same coins does not create new combinations.','3~The combination containing just coin 5 also counts.','Read the last denomination row at the requested amount.','The final table cell contains 4.']]);
add(543,'Find the longest path between any two nodes in the tree, measured in edges.','Return one branch depth to a parent, but compare the sum of both branch depths for the diameter.',[
[16,'What depth does a missing child contribute?','0','1~A missing child adds no node to the downward path.','-1~This implementation uses zero as its null base case.','Recursion needs a zero contribution for an empty subtree.','depth(null) immediately returns 0.'],
[31,'At node 1, the left depth is 2 and right depth is 1. What through-path improves the diameter?','3','2~A path through the node may use both branches.','4~Adding another one would overcount the through-path in edges.','Connect the deepest left and right endpoints through this node.','2 + 1 equals 3.'],
[33,'What diameter is returned for this tree?','3 edges','3 nodes~The requested measure is edges; this path contains four nodes.','2 edges~That considers only a single side.','Use the largest through-path recorded anywhere.','The path connecting a deep left leaf to the right child has three edges.']]);
add(560,'Count contiguous subarrays whose values add to k by matching prefix-sum differences.','Look up sum - k before storing the current prefix, and keep occurrence counts rather than a simple set.',[
[1,'Why is prefix sum 0 stored once before reading any values?','To count matching subarrays that begin at index 0','To count an empty subarray as the final answer~The seed helps later nonempty matches; it does not increment the answer itself.','Because input values are all zero~This input contains ones.','A start-at-zero subarray has no earlier elements to subtract.','Its earlier prefix is the empty prefix with sum 0.'],
[11,'The running sum is 2 and k is 2. One earlier prefix has sum 0. How does count change?','Increase by 1','Stay unchanged~The difference 2 - 0 exactly matches k.','Increase by 2~The map frequency, not k, determines the increment.','Each matching earlier prefix identifies one starting boundary.','freq.get(sum - k) is 1.'],
[18,'For [1,1,1] and k = 2, how many matching contiguous subarrays exist?','2','1~The first two and last two ones are different subarrays.','3~The full length-three array sums to 3, not 2.','Count the two neighboring pairs.','The intervals are indices 0..1 and 1..2.']]);
add(567,'Look for a substring whose letter counts exactly match the smaller string.','A matching window has the same length and frequencies; its character order may differ.',[
[1,'The smaller string has length 2 and the larger length 8. Can a matching window fit?','Yes','No, because the lengths differ~Only the candidate substring must match length 2.','Only if both full strings are equal~We search inside the larger string.','Compare the desired window width with available characters.','2 is no larger than 8.'],
[13,'The scanning window grows to length 3 while the target length is 2. What must happen?','Remove its leftmost character','Remove its newest character~Sliding the window forward keeps the new right edge.','Keep all three~A three-character window cannot be a permutation of a two-character string.','Maintain a fixed window width equal to the smaller string.','Advance the left boundary by one.'],
[26,'The window ba contains the same letters as ab. What does the function return?','true','false, because the order is reversed~A permutation may reorder characters.','2~The result is a boolean, not the window length.','Compare character frequencies, not character positions.','Both windows contain one a and one b.']]);
add(572,'Check whether a complete branch of one tree has exactly the same values and shape as another tree.','Finding the candidate root value is not enough; both child subtrees must match recursively.',[
[4,'The first candidate compares node 3 against subtree root 4. Can these roots match?','No','Yes, because 4 exists somewhere below~This comparison checks an exact match at the current root.','Only the children matter~The root values must match too.','An exact same-tree comparison begins with the node values.','3 differs from 4.'],
[13,'Both compared children are null. What does this branch comparison return?','true','false~Matching empty positions preserve the same shape.','Continue into a child~Neither side has a child to visit.','An empty subtree equals another empty subtree.','Both missing positions match.'],
[24,'A complete match was found at main-tree node 4. Is subRoot a subtree?','Yes','No, because the whole root is 3~The match may start below the main root.','Only if every other branch matches~Unrelated branches outside the matched subtree do not matter.','One exact subtree match settles the existence question.','The match at node 4 returns true up the call stack.']]);
add(621,'Schedule repeated tasks with the required cooldown while minimizing the total CPU cycles.','Idle cycles count toward elapsed time; a cooled task is unavailable even if it has many repetitions remaining.',[
[1,'What frequencies are counted for this workload before scheduling?','A: 3 and B: 3','A: 1 and B: 1~Each repeated occurrence must be scheduled.','A: 3 and B: 2~There are three copies of both task types.','Group identical task labels.','The workload contains three As and three Bs.'],
[23,'After running a task with one repetition still remaining, where does that repetition go?','Into the cooldown queue until ready time 6','Immediately back into the ready heap~It cannot run again before its cooldown.','Nowhere; it is discarded~The remaining occurrence must still be scheduled.','Separate ready work from work waiting for its cooldown.','Store [remaining count 1, ready time 6].'],
[43,'Six actual tasks have finished, including necessary idle gaps. What elapsed time is returned?','8','6~That ignores the cooldown gaps between repeated task types.','9~The final task does not need a trailing cooldown.','Count CPU cycles, including idle cycles before completion.','Both the ready heap and cooldown queue empty at time 8.']]);
add(622,'Store a queue inside a fixed array and wrap its positions around when reaching the end.','Track count separately so equal-looking wrapped indices do not confuse full and empty states.',[
[2,'With head 0 and count 0 in capacity 3, which slot receives the first value?','Slot 0','Slot 1~Insertion uses head + count before incrementing count.','Slot 2~The first insertion begins at the head.','Compute (head + count) modulo capacity.','(0 + 0) % 3 is 0.'],
[14,'Three items already fill capacity three. What does enQueue(4) do?','Return false without changing the queue','Overwrite the oldest item~This queue rejects insertion when full.','Grow the array~The allocated capacity is fixed.','Check count against capacity before writing.','count === capacity means full.'],
[27,'After one removal and a wrapped insertion, head is 1 and count is 3. What does Rear return?','4 from slot 0','3 from slot 2~The new last value wrapped back to slot 0.','1 from slot 1~That slot is the front position, not necessarily the rear.','Rear index is (head + count - 1) % capacity.','(1 + 3 - 1) % 3 is 0, holding 4.']]);
add(647,'Count every substring that reads the same forward and backward.','Substrings at different positions count separately even when they spell the same text.',[
[2,'The first expansion compares a with itself. Does this single-character substring count?','Yes','No, palindromes need two characters~Every single character is a palindrome.','Only once for the entire string~Each position defines a different one-character substring.','The two ends already match.','Increment the count for the first a.'],
[9,'Expanding around the middle a now compares the two outer as. Which new palindrome is counted?','aaa','aa~This odd-length expansion includes the center plus both outer characters.','No new palindrome~Equal outer characters extend the known inner palindrome.','An odd center grows by two characters at a time.','Indices 0 through 2 spell aaa.'],
[19,'How many palindromic substrings are in aaa?','6','3~That counts only the single-character substrings.','1~Identical text at different positions still yields distinct substrings.','Count three singles, two pairs, and one triple.','3 + 2 + 1 equals 6.']]);
add(649,'Simulate senators taking turns to ban opponents until only one party remains.','A surviving senator returns at index + n to preserve the next-round turn order.',[
[2,'The second character is D at position 1. Which queue receives index 1?','Dire','Radiant~R and D belong to separate parties.','Both~One senator belongs to one party.','Use the current character to choose the party queue.','D stands for Dire.'],
[5,'Radiant index 0 acts before Dire index 1. Where is the surviving Radiant senator requeued?','Index 2','Index 0~That would incorrectly let it act again in the same turn order.','Index 1~That is the eliminated opponent\'s position.','Add one full senate length to the survivor\'s index.','0 + n, with n = 2, is 2.'],
[6,'Dire has no senators remaining. Which party wins?','Radiant','Dire~Its only senator was banned before acting.','Neither~A party still has an active senator.','The nonempty queue determines the surviving party.','Radiant still has its requeued senator.']]);
add(658,'Keep the four values closest to a target in a sorted array, preferring smaller values on ties.','When the endpoint distances tie, discard the larger right endpoint to preserve the smaller value.',[
[2,'Values 1 and 5 are both distance 2 from target 3. Which endpoint should be discarded?','5 on the right','1 on the left~Ties favor keeping the smaller value.','Neither~The window still has five values but only four are requested.','The problem specifies how to break equal-distance ties.','Keep 1 and remove 5.'],
[3,'Discarding the far-right value changes which boundary?','Decrease right by 1','Increase left by 1~That would discard the left endpoint instead.','Increase right by 1~That expands the window.','Move the chosen boundary toward the center.','right-- removes arr[4] = 5.'],
[6,'Which four closest values are returned for target 3?','[1, 2, 3, 4]','[2, 3, 4, 5]~The tie between 1 and 5 favors 1.','[1, 2, 3]~Exactly four values are requested.','Read the remaining sorted window.','The only removed endpoint was 5.']]);
add(678,'Check whether parentheses can be balanced when stars may act as an opening, a closing, or nothing.','Track the range of possible unmatched opens; a negative maximum means every interpretation fails.',[
[1,'The first character is a definite opening parenthesis. How does the possible-open band change?','From [0,0] to [1,1]','It stays [0,0]~A definite opening must be counted.','To [0,1]~Only a star permits multiple interpretations here.','A fixed opening adds one to every possible count.','Increment both low and high.'],
[4,'The next character closes the open parenthesis. What band remains?','[0,0]','[1,1]~The closing character consumes the unmatched opening.','[-1,-1]~There was one opening available to close.','Subtract one from both current bounds.','[1,1] becomes [0,0].'],
[7,'At the end, low is zero. Is a fully balanced interpretation possible?','Yes','No, high must be negative~A negative high would mean failure, not balance.','Only if the string contained a star~A string without stars may already be balanced.','Zero remaining openings must be among the possible counts.','The final band includes zero.']]);
add(680,'Check whether deleting at most one character can make the string a palindrome.','At the first mismatch, try deleting either endpoint; committing to only one side may miss a valid answer.',[
[3,'The outer characters match. What happens to the two pointers?','Move both inward','Delete one matching character~There is no need to spend the deletion on a matching pair.','Move only left~Both matching endpoints have been settled.','Matching ends can stay in the palindrome.','Increment left and decrement right.'],
[6,'The next pair mismatches. Which remaining substrings must be considered?','Skip left OR skip right','Skip both~Only one deletion is allowed.','Return false immediately~One deletion may repair this mismatch.','The mismatched pair cannot both remain unchanged.','Test [left+1,right] and [left,right-1].'],
[8,'The skip-left branch is a palindrome. What can the whole function conclude?','true','false unless the other branch also works~Only one successful deletion is required.','Delete another character~The remainder already passes with the allowed one deletion.','The two alternatives are joined by logical OR.','One successful branch is enough.']]);
add(682,'Apply score operations while keeping the valid previous records on a stack.','Cancel removes the most recent valid record; later operations must use the remaining stack.',[
[5,'The stack contains scores 5 then 2. Which score does C cancel?','2','5~C removes the most recently added score, at the stack top.','Both~C cancels only one record.','A stack removes the last record first.','The top record is 2.'],
[8,'After cancellation, the top score is 5. What does D push?','10','4~2 was canceled and must not be used.','5~D doubles rather than copies the top score.','Use the current valid top value.','2 times 5 is 10.'],
[11,'The remaining records are 5, 10, and 15. What total is returned?','30','15~The answer sums every valid record, not just the top one.','32~The canceled score 2 must be excluded.','Add all records still on the stack.','5 + 10 + 15 equals 30.']]);
add(684,'Find the extra edge that closes a cycle in an otherwise tree-like graph.','Compare component roots rather than endpoint labels; different nodes may already be connected.',[
[4,'The first edge joins roots 1 and 2. Does it create a cycle?','No; merge the two components','Yes, because the endpoints differ~Different roots mean there was no prior path between them.','Only if the ranks match~Equal ranks affect balancing, not cycle existence.','A cycle needs an already existing connection.','The endpoint roots differ.'],
[12,'For edge [2,3], both roots are 1. What does union report?','Failure: this edge closes a cycle','Success: labels 2 and 3 differ~Component representatives, not labels, determine existing connectivity.','Delete root 1~The redundant item is an edge, not the representative node.','Both endpoints already lie in the same connected set.','Adding another connection creates a cycle.'],
[13,'Which edge should be returned as redundant?','[2, 3]','[1, 2]~That first edge joined separate components.','[1, 3]~That edge also joined a new component safely.','Return the edge whose union failed.','The failure occurred on the last edge [2,3].']]);
